const BASE = "{{BASE}}";
const TOKEN = "{{PRODUCER_TOKEN}}";

async function send(title, body, level = "info", to = { to_all: true }) {
  const r = await fetch(BASE + "/api/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + TOKEN },
    body: JSON.stringify({ title, body, level, ...to })
  });
  if (!r.ok) throw new Error("HTTP " + r.status);
  return (await r.json()).msg.id;
}

send("构建完成", "main 分支 CI 通过", "success", { to_groups: ["研发"] });

